/**
 * Typed client for the booking payment-plan endpoints.
 *
 * Mirrors `server/routes/payments.ts`. A read returns the confirmed plan (or null
 * when a booking has none yet) with its dated installment lines, each carrying both
 * the stored status and the derived display status; the flags `canCreate` and
 * `canRecord` come from the server so the builder button and the per-row record action
 * appear only for roles that may actually use them.
 *
 * Confirming takes the same configuration the live preview built through
 * `payment-plan-calc`, and the schedule it returns is generated by the shared builder —
 * so the rows here are exactly the lines the dialog showed.
 */

import type {
  Frequency,
  InstallmentDisplayStatus,
  InstallmentKind,
  InstallmentStatus,
} from "@shared/payment-plans"

import type { PaymentAllocationInput, PaymentMethod } from "@shared/payments"

import type { LedgerEntry } from "@shared/ledger"

import { api } from "./api"

export interface PaymentPlan {
  id: string

  bookingId: string

  currency: string

  netAmount: number

  downPaymentPercent: number

  charges: number

  frequency: Frequency

  customIntervalDays: number | null

  installmentCount: number

  balloonAmount: number

  startDate: string

  status: string

  notes: string | null

  createdByUserId: string

  createdByName: string

  createdAt: string

  confirmedAt: string
}

export interface Installment {
  id: string

  planId: string

  bookingId: string

  number: number

  kind: InstallmentKind

  dueDate: string

  amount: number

  charges: number

  total: number

  paidAmount: number

  status: InstallmentStatus

  displayStatus: InstallmentDisplayStatus

  // --- Computed at read; never stored time-states --------------------------
  //
  // These fold the payment trail, the late-fee sweep, and any logged promise onto
  // the line the schedule shows. They are read-time derivations, so a line with no
  // payment yet reports nulls rather than an invented date, and a line nobody has
  // chased reports zero late days rather than a guess. The existing keys above are
  // unchanged; this block is purely additive.

  /** `YYYY-MM-DD` the line was fully paid, or null while any balance remains. */
  paidDate: string | null

  /** Method of the payment that settled the line, or null when it is not settled. */
  method: PaymentMethod | null

  /** Receipt number for the payment that settled the line, or null. */
  receiptNumber: string | null

  /** Payment id behind that receipt, so the row can link to the receipt document. */
  receiptId: string | null

  /** Whole days the line has been overdue as of the tenant's today; 0 when not late. */
  lateDays: number

  /** Unwaived late charge assessed on the line, in whole major units. */
  lateCharge: number

  /** `YYYY-MM-DD` a logged promise to pay reaches, or null; reminders pause until then. */
  promiseToPayDate: string | null
}

export interface PaymentPlanResponse {
  plan: PaymentPlan | null

  installments: Installment[]

  currency: string

  canCreate: boolean

  canRecord: boolean

  /**
   * Whether the booked unit is sold in installments at all. False for a lump-sum-only
   * unit, whose booking has no schedule to build: `canCreate` already carries that, and
   * this flag is what lets the booking page say why the builder is not there rather than
   * leaving an empty card.
   */
  allowsInstallments: boolean

  /** The unit's sale mode as this tenant names it, so the note can quote it. */
  saleMode: string | null
}

export interface RecordPaymentResponse {
  installment: Installment

  currency: string

  payment: Payment

  ledgerEntry: LedgerEntry
}

/** A recorded payment header, as the server returns it (a receipt is minted on write). */

export interface Payment {
  id: string

  customerId: string

  bookingId: string | null

  currency: string

  method: PaymentMethod

  amount: number

  receiptNumber: string | null

  note: string | null

  recordedByUserId: string

  recordedByName: string

  receivedAt: string

  createdAt: string
}

/** A payment row joined to the customer's name for the receipts list. */

export interface PaymentListItem extends Payment {
  customerName: string | null
}

/** An open installment with its remaining balance and the booking reference to label it. */

export interface OpenInstallment extends Installment {
  remaining: number

  bookingReference: string
}

/** One allocated line on a printable receipt. */

export interface ReceiptLine {
  installmentId: string

  number: number

  kind: InstallmentKind

  dueDate: string

  installmentTotal: number

  paidAmount: number

  allocated: number

  bookingReference: string

  displayStatus: InstallmentDisplayStatus
}

/** The tenant block printed above a receipt, drawn from the organization profile. */

export interface ReceiptTenantBlock {
  name: string

  legalName: string | null

  registrationNumber: string | null

  addressLine1: string | null

  addressLine2: string | null

  city: string | null

  stateRegion: string | null

  postalCode: string | null

  countryCode: string | null

  phone: string | null

  email: string | null
}

/** The customer block a receipt is addressed to. */

export interface ReceiptCustomerBlock {
  name: string

  phone: string

  email: string | null

  addressLine1: string | null

  addressLine2: string | null

  city: string | null

  stateRegion: string | null

  postalCode: string | null

  country: string | null
}

/** The whole printable receipt: header, tenant, customer, and the allocated lines. */

export interface ReceiptView {
  payment: Payment

  tenant: ReceiptTenantBlock

  customer: ReceiptCustomerBlock | null

  lines: ReceiptLine[]

  currency: string
}

export interface OpenInstallmentsResponse {
  installments: OpenInstallment[]

  currency: string

  canRecord: boolean
}

export interface ListPaymentsResponse {
  payments: PaymentListItem[]

  currency: string

  canCreate: boolean
}

export interface LedgerResponse {
  entries: LedgerEntry[]

  currency: string

  balance: number
}

/** One payment split across installments. The allocation total must equal `amount`. */

export interface RecordAllocationInput {
  customerId: string

  method: PaymentMethod

  amount: number

  allocations: PaymentAllocationInput[]

  bookingId?: string | null

  receivedAt?: string

  note?: string | null
}

export interface RecordAllocationResponse {
  payment: Payment

  ledgerEntry: LedgerEntry
}

/** The builder's configuration, matching the confirm endpoint's validated body. */

export interface ConfirmPlanInput {
  netAmount: number

  downPaymentPercent: number

  charges: number

  frequency: Frequency

  customIntervalDays: number | null

  installmentCount: number

  balloonAmount: number

  startDate: string

  notes?: string | null
}

export const paymentsApi = {
  readPlan: (bookingId: string, signal?: AbortSignal) =>
    api.get<PaymentPlanResponse>(
      `/api/bookings/${bookingId}/payment-plan`,

      signal,
    ),

  confirmPlan: (bookingId: string, config: ConfirmPlanInput) =>
    api.post<PaymentPlanResponse>(
      `/api/bookings/${bookingId}/payment-plan/confirm`,

      config,
    ),

  recordPayment: (installmentId: string, amount: number) =>
    api.post<RecordPaymentResponse>(
      `/api/payment-installments/${installmentId}/payments`,

      { amount },
    ),

  /** Record one payment and allocate it across a customer's open installments. */
  recordAllocated: (input: RecordAllocationInput) =>
    api.post<RecordAllocationResponse>("/api/payments", input),

  /** The allocation dialog's source: every installment still carrying a balance. */
  openInstallments: (customerId: string, signal?: AbortSignal) =>
    api.get<OpenInstallmentsResponse>(
      `/api/customers/${customerId}/open-installments`,

      signal,
    ),

  /** The recent receipts, newest first; optionally scoped to one customer. */
  list: (customerId: string | null, signal?: AbortSignal) =>
    api.get<ListPaymentsResponse>(
      customerId
        ? `/api/payments?customerId=${encodeURIComponent(customerId)}`
        : "/api/payments",

      signal,
    ),

  /** The whole printable receipt for one payment. */
  receipt: (paymentId: string, signal?: AbortSignal) =>
    api.get<ReceiptView>(`/api/payments/${paymentId}`, signal),

  /** The customer's append-only account ledger, with the running balance folded in. */
  ledger: (customerId: string, signal?: AbortSignal) =>
    api.get<LedgerResponse>(`/api/customers/${customerId}/ledger`, signal),
}
